function normalizeLanguage(language?: string): string {
  if (!language) return "en";
  if (language.toLowerCase().startsWith("pt")) return "pt-BR";
  if (language.toLowerCase().startsWith("es")) return "es";
  if (language.toLowerCase().startsWith("de")) return "de";
  if (language.toLowerCase().startsWith("pl")) return "pl";
  return "en";
}

export function createTranslator(language?: string) {
  const lang = normalizeLanguage(language);
  const dictionary = messages[lang] ?? messages.en;
  const added = addedMessages[lang] ?? addedMessages.en;
  return (key: TranslationKey): string => dictionary[key] ?? added[key] ?? addedMessages.en[key] ?? key;
}

