export function weatherConditionLabel(condition: string, language?: string): string {
  const dictionary = weatherMessages[normalizeLanguage(language)] ?? weatherMessages.en;
  return dictionary[condition] ?? condition.replaceAll("_", " ").replaceAll("-", " ");
}
